// Split out of the former single 16,000-line catalogs.ts (2026-07-21).
//
// One module per language so a bundle only carries the language it renders:
// the combined file put all four in every entry chunk, which was 698 KB — 55%
// of Blanc's boot JS — in a window whose own chrome is not even translated.
// See BLANC_REFINEMENT_PLAN.md, "Pillar 1, the real headline".
//
// Contents are unchanged from the combined file. English remains the source of
// truth and the fallback; see ./catalogs.ts for the loader.

